package com.ynxweb4.shop;
import org.junit.Test;import org.json.*;import static org.junit.Assert.*;
public final class CartQuantityTest {
 JSONArray lines()throws Exception{return new JSONArray().put(new JSONObject().put("ProductID","ab").put("VariantID","c").put("Quantity",1)).put(new JSONObject().put("ProductID","a").put("VariantID","bc").put("Quantity",3));}
 @Test public void exactTuplePreservesForeignLineAndOriginalSnapshot()throws Exception{JSONArray original=lines();String bytes=original.toString();JSONArray next=CartQuantity.change(original,"ab","c",1,20);assertEquals(bytes,original.toString());assertEquals(20,next.getJSONObject(0).getInt("Quantity"));assertEquals(3,next.getJSONObject(1).getInt("Quantity"));assertEquals(1,CartQuantity.change(next,"ab","c",20,1).getJSONObject(0).getInt("Quantity"));}
 @Test public void oldQuantityMissingAndAmbiguousLineCannotEdit()throws Exception{JSONArray original=lines();String bytes=original.toString();assertThrows(SecurityException.class,()->CartQuantity.change(original,"ab","c",2,3));assertThrows(SecurityException.class,()->CartQuantity.change(original,"missing","c",1,2));assertEquals(bytes,original.toString());JSONArray duplicate=lines().put(lines().getJSONObject(0));assertThrows(SecurityException.class,()->CartQuantity.change(duplicate,"ab","c",1,2));}
 @Test public void invalidBoundsPreserveDraft()throws Exception{JSONArray original=lines();String bytes=original.toString();for(int quantity:new int[]{0,21,-1,Integer.MAX_VALUE})assertThrows(IllegalArgumentException.class,()->CartQuantity.change(original,"ab","c",1,quantity));assertEquals(bytes,original.toString());}
 @Test public void encryptedDraftColdRestoreRetainsExactQuantityAndUnknownCheckoutBlocksIt()throws Exception{BuyerJourneyTest.Memory store=new BuyerJourneyTest.Memory();BuyerJourneyTest.cart(store);NativeCart.edit(store,BuyerJourneyTest.A,CartQuantity.change(new JSONArray(store.get("cart:"+BuyerJourneyTest.A)),"p","v",1,4));assertEquals(4,new JSONArray(store.get("cart:"+BuyerJourneyTest.A)).getJSONObject(0).getInt("Quantity"));store.put("checkout:"+BuyerJourneyTest.A,new JSONObject().put("account",BuyerJourneyTest.A).put("phase","unknown").put("key","original").toString());String before=store.get("cart:"+BuyerJourneyTest.A);assertThrows(CheckoutIntent.UnresolvedException.class,()->NativeCart.edit(store,BuyerJourneyTest.A,CartQuantity.change(new JSONArray(before),"p","v",4,5)));assertEquals(before,store.get("cart:"+BuyerJourneyTest.A));}
}
